## Code Example

```javascript
function minPalRemoval(s){
  const n = s.length;
  const dp = Array.from({length:n}, ()=> Array(n).fill(0));
  for(let i=n-1;i>=0;i--){
    dp[i][i] = 1;
    for(let j=i+1;j<n;j++){
      dp[i][j] = 1 + dp[i+1][j];
      for(let k=i+1;k<=j;k++){
        if(s[i] === s[k]){
          const left = (k-1 >= i+1) ? dp[i+1][k-1] : 0;
          const right = (k+1 <= j) ? dp[k+1][j] : 0;
          dp[i][j] = Math.min(dp[i][j], left + right);
        }
      }
    }
  }
  return n ? dp[0][n-1] : 0;
}
```

